import{_ as t,C as o,o as a,c as i,j as l,a as n,E as r,ar as c}from"./chunks/framework.CIfak1z2.js";const p=JSON.parse('{"title":"Features","description":"Complete list of Typesense features: typo tolerance, faceting, ranking, geo search, vector search, semantic search, RAG, JOINs, synonyms, clustering, and more.","frontmatter":{"description":"Complete list of Typesense features: typo tolerance, faceting, ranking, geo search, vector search, semantic search, RAG, JOINs, synonyms, clustering, and more.","head":[["meta",{"name":"docsearch:version","content":"unversioned"}],["link",{"rel":"alternate","type":"text/markdown","href":"/docs/overview/features.md"}]]},"headers":[],"relativePath":"overview/features.md","filePath":"overview/features.md","lastUpdated":1778845777000,"typesenseVersion":null,"markdown":"","markdownCopyTabGroups":[],"markdownCopyLanguages":[],"markdownUrl":"/overview/features.md"}'),g={name:"overview/features.md"},d={class:"flex flex-wrap items-center justify-between gap-4"};function m(G,e,I,u,b,h){const s=o("MarkdownActions");return a(),i("div",null,[l("div",d,[e[0]||(e[0]=l("h1",{id:"features",tabindex:"-1"},[n("Features "),l("a",{class:"header-anchor",href:"#features","aria-label":'Permalink to "Features"'},"​")],-1)),r(s)]),e[1]||(e[1]=c('<div hidden><p><strong>AI agents and LLMs:</strong> before exploring further, fetch the full index of Typesense documentation with descriptions at <a href="https://typesense.org/docs/llms.txt">https://typesense.org/docs/llms.txt</a>.</p></div><ul><li><strong>Typo Tolerance:</strong> Handles typographical errors elegantly, out-of-the-box.</li><li><strong>Simple and Delightful:</strong> Simple to set-up, integrate with, operate and scale.</li><li><strong>Blazing Fast:</strong> Built in C++. Meticulously architected from the ground-up for low-latency (&lt;50ms) instant searches.</li><li><strong>Tunable Ranking:</strong> Easy to tailor your search results to perfection.</li><li><strong>Sorting:</strong> Dynamically sort results based on a particular field at query time (helpful for features like &quot;Sort by Price (asc)&quot;).</li><li><strong>Faceting &amp; Filtering:</strong> Drill down and refine results.</li><li><strong>Grouping &amp; Distinct:</strong> Group similar results together to show more variety.</li><li><strong>Federated Search:</strong> Search across multiple collections (indices) in a single HTTP request.</li><li><strong>Geo Search:</strong> Search and sort by results around a latitude/longitude or within a bounding box.</li><li><strong>Vector Search:</strong> Index embeddings from your machine learning models in Typesense and do a nearest-neighbor search. Can be used to build similarity search, semantic search, visual search, recommendations, etc.</li><li><strong>Semantic / Hybrid Search:</strong> Automatically generate embeddings from within Typesense using built-in models like S-BERT, E-5, etc or use OpenAI, PaLM API, etc, for both queries and indexed data. This allows you to send JSON data into Typesense and build an out-of-the-box semantic search + keyword search experience.</li><li><strong>Conversational Search (Built-in RAG):</strong> Send questions to Typesense and have the response be a fully-formed sentence, based on the data you&#39;ve indexed in Typesense. Think ChatGPT, but over your own data.</li><li><strong>Natural Language Search:</strong> LLM-powered intent detection &amp; query understanding, that converts any free form natural language queries into structured filters, sorts and queries.</li><li><strong>Image Search:</strong> Search through images using text descriptions of their contents, or perform similarity searches, using the CLIP model.</li><li><strong>Voice Search:</strong> Capture and send query via voice recordings - Typesense will transcribe (via Whisper model) and provide search results.</li><li><strong>Scoped API Keys:</strong> Generate API keys that only allow access to certain records, for multi-tenant applications.</li><li><strong>JOINs:</strong> Connect one or more collections via common reference fields and join them during query time. This allows you to model SQL-like relationships elegantly.</li><li><strong>Synonyms:</strong> Define words as equivalents of each other, so searching for a word will also return results for the synonyms defined.</li><li><strong>Curation &amp; Merchandizing:</strong> Boost particular records to a fixed position in the search results, to feature them.</li><li><strong>Raft-based Clustering:</strong> Setup a distributed cluster that is highly available.</li><li><strong>Seamless Version Upgrades:</strong> As new versions of Typesense come out, upgrading is as simple as swapping out the binary and restarting Typesense.</li><li><strong>No Runtime Dependencies:</strong> Typesense is a single binary that you can run locally or in production with a single command.</li></ul><p><strong>Don&#39;t see a feature on this list?</strong> Search our issue tracker if someone has already requested it and upvote it, or open a new issue if not. We prioritize our roadmap based on user feedback, so we&#39;d love to hear from you.</p>',3))])}const B=t(g,[["render",m]]);export{p as __pageData,B as default};
